import { stripTypeScriptTypes } from 'node:module';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
await mkdir('plugins/spec100/runtime', { recursive: true });
const source = await readFile('src/runtime.cts', 'utf8');
await writeFile('plugins/spec100/runtime/spec100.cjs',
  '// Generated by npm run build. Source: src/runtime.cts.\n' + stripTypeScriptTypes(source));
